#[derive(Clone)]
pub struct FunctionDecoratorInfo {
    pub flags: FunctionTypeFlags,
    pub deprecation_message: Option<String>,
}

// analyzer/decorators.ts:56
// Scans through the decorators to find a few built-in decorators
// that affect the function flags.
pub fn get_function_info_from_decorators(
    evaluator: &TypeEvaluator,
    node: FunctionNode,
    is_in_class: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> FunctionDecoratorInfo {
    let file_info = node_info.get_file_info(node.0);
    let mut flags = FunctionTypeFlags::None;
    let mut deprecation_message: Option<String> = None;

    if is_in_class {
        // The "__new__" magic method is not an instance method.
        // It acts as a static method instead.
        if node.d().name.get().d().value == "__new__" {
            flags |= FunctionTypeFlags::ConstructorMethod;
        }

        // Several magic methods are treated as class methods implicitly
        // by the runtime. Check for these here.
        let implicit_class_methods = ["__init_subclass__", "__class_getitem__"];
        if implicit_class_methods
            .iter()
            .any(|name| node.d().name.get().d().value == *name)
        {
            flags |= FunctionTypeFlags::ClassMethod;
        }
    }

    let decorators = node.d().decorators.borrow().clone();
    for decorator_node in decorators {
        // Some stub files (e.g. builtins.pyi) rely on forward declarations of decorators.
        let mut evaluator_flags = if file_info.is_stub_file {
            EvalFlags::ForwardRefs
        } else {
            EvalFlags::None
        };
        if decorator_node.d().expr.get().node_type != ParseNodeType::Call {
            evaluator_flags |= EvalFlags::CallBaseDefaults;
        }

        let decorator_type_result =
            evaluator.get_type_of_expression(decorator_node.d().expr.get(), evaluator_flags, None);
        let decorator_type = decorator_type_result.type_.get();

        if is_function(decorator_type) {
            let decorator_function = FunctionType(decorator_type);
            if FunctionType::is_built_in(decorator_function, Some(&["abstractmethod"]))
            {
                if is_in_class {
                    flags |= FunctionTypeFlags::AbstractMethod;
                }
            } else if FunctionType::is_built_in(decorator_function, Some(&["final"])) {
                flags |= FunctionTypeFlags::Final;
            } else if FunctionType::is_built_in(decorator_function, Some(&["override"]))
            {
                flags |= FunctionTypeFlags::Overridden;
            } else if FunctionType::is_built_in(
                decorator_function,
                Some(&["type_check_only"]),
            ) {
                flags |= FunctionTypeFlags::TypeCheckOnly;
            } else if FunctionType::is_built_in(
                decorator_function,
                Some(&["no_type_check"]),
            ) {
                flags |= FunctionTypeFlags::NoTypeCheck;
            } else if FunctionType::is_built_in(decorator_function, Some(&["overload"]))
            {
                flags |= FunctionTypeFlags::Overloaded;
            }
        } else if is_class(decorator_type) {
            let decorator_class = ClassType(decorator_type);
            if TypeBase::is_instantiable(decorator_type) {
                if ClassType::is_built_in(decorator_class, Some(&["staticmethod"])) {
                    if is_in_class {
                        flags |= FunctionTypeFlags::StaticMethod;
                    }
                } else if ClassType::is_built_in(
                    decorator_class,
                    Some(&["classmethod"]),
                ) && is_in_class
                {
                    flags |= FunctionTypeFlags::ClassMethod;
                }
            } else if ClassType::is_built_in(decorator_class, Some(&["deprecated"])) {
                deprecation_message = decorator_class
                    .d()
                    .priv_
                    .borrow()
                    .cold().deprecated_instance_message
                    .clone();
            }
        }
    }

    FunctionDecoratorInfo {
        flags,
        deprecation_message,
    }
}

// analyzer/decorators.ts:131
// Transforms the input function type into an output type based on the
// decorator function described by the decoratorNode.
pub fn apply_function_decorator(
    evaluator: &TypeEvaluator,
    input_function_type: P<Type>,
    undecorated_type: FunctionType,
    decorator_node: DecoratorNode,
    function_node: FunctionNode,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    let file_info = node_info.get_file_info(decorator_node.0);

    // Some stub files (e.g. builtins.pyi) rely on forward declarations of decorators.
    let mut evaluator_flags = if file_info.is_stub_file {
        EvalFlags::ForwardRefs
    } else {
        EvalFlags::None
    };
    if decorator_node.d().expr.get().node_type != ParseNodeType::Call {
        evaluator_flags |= EvalFlags::CallBaseDefaults;
    }

    let decorator_type_result =
        evaluator.get_type_of_expression(decorator_node.d().expr.get(), evaluator_flags, None);
    let decorator_type = decorator_type_result.type_.get();

    if is_function(decorator_type)
        && FunctionType::is_built_in(
            FunctionType(decorator_type),
            Some(&["disjoint_base"]),
        )
    {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &LocMessage::disjoint_base_function(),
            decorator_node.d().expr.get(),
            None,
        );
        return input_function_type;
    }

    // Special-case the "overload" because it has no definition. Older versions of typeshed
    // defined "overload" as an object, but newer versions define it as a function.
    if ((is_instantiable_class(decorator_type)
        && ClassType::is_special_built_in(ClassType(decorator_type), Some("overload")))
        || (is_function(decorator_type)
            && FunctionType::is_built_in(
                FunctionType(decorator_type),
                Some(&["overload"]),
            )))
        && is_function(input_function_type)
    {
        let input_shared = FunctionType(input_function_type).d().shared.get();
        input_shared
            .flags
            .set(input_shared.flags.get() | FunctionTypeFlags::Overloaded);
        let undecorated_shared = undecorated_type.d().shared.get();
        undecorated_shared
            .flags
            .set(undecorated_shared.flags.get() | FunctionTypeFlags::Overloaded);
        return input_function_type;
    }

    if decorator_node.d().expr.get().node_type == ParseNodeType::Call {
        let call_node = CallNode(decorator_node.d().expr.get());
        let decorator_call_type = evaluator
            .get_type_of_expression(
                call_node.d().left_expr.get(),
                evaluator_flags | EvalFlags::CallBaseDefaults,
                None,
            )
            .type_
            .get();

        if is_function(decorator_call_type) {
            let decorator_call_function = FunctionType(decorator_call_type);
            if decorator_call_function.d().shared.get().name == "__dataclass_transform__"
                || FunctionType::is_built_in(
                    decorator_call_function,
                    Some(&["dataclass_transform"]),
                )
            {
                undecorated_type
                    .d()
                    .shared
                    .get()
                    .set_cold(|cold| &mut cold.decorator_data_class_behaviors, validate_data_class_transform_decorator(
                        evaluator, call_node, node_info,
                    ));
                return input_function_type;
            }
        }
    }

    // Clear the PartiallyEvaluated flag in the input if it's set so
    // it doesn't propagate to the decorated type.
    let decorator_arg = if is_function(input_function_type)
        && FunctionType::is_partially_evaluated(FunctionType(input_function_type))
    {
        let input_function = FunctionType(input_function_type);
        FunctionType::clone_with_new_flags(
            input_function,
            input_function.d().shared.get().flags.get() & !FunctionTypeFlags::PartiallyEvaluated,
        )
        .0
    } else {
        input_function_type
    };

    let mut return_type =
        get_type_of_decorator(evaluator, decorator_node, decorator_arg, node_info);

    // Check for some built-in decorator types with known semantics.
    if is_function(decorator_type) {
        let decorator_function = FunctionType(decorator_type);
        if FunctionType::is_built_in(decorator_function, Some(&["abstractmethod"])) {
            return input_function_type;
        }

        if FunctionType::is_built_in(decorator_function, Some(&["type_check_only"])) {
            let undecorated_shared = undecorated_type.d().shared.get();
            undecorated_shared
                .flags
                .set(undecorated_shared.flags.get() | FunctionTypeFlags::TypeCheckOnly);
            return input_function_type;
        }

        // Handle property setters and deleters.
        if decorator_node.d().expr.get().node_type == ParseNodeType::MemberAccess {
            let member_access_node = MemberAccessNode(decorator_node.d().expr.get());
            let base_type = evaluator
                .get_type_of_expression(
                    member_access_node.d().left_expr.get(),
                    evaluator_flags | EvalFlags::MemberAccessBaseDefaults,
                    None,
                )
                .type_
                .get();

            if is_property(base_type) {
                let member_name = member_access_node.d().member.get().d().value.clone();
                if member_name == "setter" {
                    if is_function(input_function_type) {
                        validate_property_method(
                            evaluator,
                            FunctionType(input_function_type),
                            decorator_node.0,
                        );
                        return clone_property_with_setter(
                            evaluator,
                            base_type,
                            FunctionType(input_function_type),
                            function_node,
                            node_info,
                        );
                    } else {
                        return input_function_type;
                    }
                } else if member_name == "deleter" {
                    if is_function(input_function_type) {
                        validate_property_method(
                            evaluator,
                            FunctionType(input_function_type),
                            decorator_node.0,
                        );
                        return clone_property_with_deleter(
                            evaluator,
                            base_type,
                            FunctionType(input_function_type),
                            function_node,
                            node_info,
                        );
                    } else {
                        return input_function_type;
                    }
                }
            }
        }
    } else if is_instantiable_class(decorator_type) {
        let decorator_class = ClassType(decorator_type);
        if ClassType::is_built_in(decorator_class, None) {
            match decorator_class.d().shared.get().name.as_str() {
                "classmethod" | "staticmethod" => {
                    let required_flag = if decorator_class.d().shared.get().name == "classmethod" {
                        FunctionTypeFlags::ClassMethod
                    } else {
                        FunctionTypeFlags::StaticMethod
                    };

                    // If the function isn't currently a class method or static method
                    // (which can happen if the function was wrapped in a decorator),
                    // add the appropriate flag.
                    if is_function(input_function_type)
                        && (FunctionType(input_function_type)
                            .d()
                            .shared
                            .get()
                            .flags
                            .get()
                            & required_flag)
                            .0
                            == 0
                    {
                        let new_function =
                            FunctionType::clone(FunctionType(input_function_type), false, None);
                        let new_shared = new_function.d().shared.get();
                        new_shared.flags.set(
                            new_shared.flags.get()
                                & !(FunctionTypeFlags::ConstructorMethod
                                    | FunctionTypeFlags::StaticMethod
                                    | FunctionTypeFlags::ClassMethod),
                        );
                        new_shared.flags.set(new_shared.flags.get() | required_flag);
                        return new_function.0;
                    }

                    return input_function_type;
                }

                "decorator" => {
                    return input_function_type;
                }

                _ => {}
            }
        }

        // Handle properties and subclasses of properties specially.
        if ClassType::is_property_class(decorator_class) {
            if is_function(input_function_type) {
                validate_property_method(
                    evaluator,
                    FunctionType(input_function_type),
                    decorator_node.0,
                );
                return create_property(
                    evaluator,
                    decorator_node,
                    decorator_class,
                    FunctionType(input_function_type),
                    node_info,
                )
                .0;
            } else if is_class_instance(input_function_type) {
                let bound_method = evaluator.get_bound_magic_method(
                    ClassType(input_function_type),
                    "__call__",
                    None,
                    None,
                    None,
                    0,
                );

                if let Some(bound_method) = bound_method
                    && is_function(bound_method)
                {
                    return create_property(
                        evaluator,
                        decorator_node,
                        decorator_class,
                        FunctionType(bound_method),
                        node_info,
                    )
                    .0;
                }

                return UnknownType::create(false).0;
            }
        }
    }

    if is_function(input_function_type) && is_function(return_type) {
        let cloned_return_type = FunctionType::clone(FunctionType(return_type), false, None);
        return_type = cloned_return_type.0;
        let return_shared = cloned_return_type.d().shared.get();

        // Copy the overload flag from the input function type.
        if FunctionType::is_overloaded(FunctionType(input_function_type)) {
            return_shared
                .flags
                .set(return_shared.flags.get() | FunctionTypeFlags::Overloaded);
        }

        // Copy the docstrings from the input function type if the
        // decorator didn't have its own docstring.
        if return_shared
            .cold().doc_string
            .as_ref()
            .is_none_or(|doc_string| doc_string.is_empty())
        {
            let doc_string = FunctionType(input_function_type)
                .d()
                .shared
                .get()
                .cold().doc_string
                .clone();
            return_shared.set_cold(|cold| &mut cold.doc_string, doc_string);
        }
    }

    return_type
}

// analyzer/decorators.ts:310
pub fn apply_class_decorator(
    evaluator: &TypeEvaluator,
    input_class_type: P<Type>,
    original_class_type: ClassType,
    decorator_node: DecoratorNode,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    let file_info = node_info.get_file_info(decorator_node.0);
    let mut flags = if file_info.is_stub_file {
        EvalFlags::ForwardRefs
    } else {
        EvalFlags::None
    };
    if decorator_node.d().expr.get().node_type != ParseNodeType::Call {
        flags |= EvalFlags::CallBaseDefaults;
    }
    let decorator_type = evaluator
        .get_type_of_expression(decorator_node.d().expr.get(), flags, None)
        .type_
        .get();

    if decorator_node.d().expr.get().node_type == ParseNodeType::Call {
        let call_node = CallNode(decorator_node.d().expr.get());
        let decorator_call_type = evaluator
            .get_type_of_expression(
                call_node.d().left_expr.get(),
                flags | EvalFlags::CallBaseDefaults,
                None,
            )
            .type_
            .get();

        if is_function(decorator_call_type) {
            let decorator_call_function = FunctionType(decorator_call_type);
            if decorator_call_function.d().shared.get().name == "__dataclass_transform__"
                || FunctionType::is_built_in(
                    decorator_call_function,
                    Some(&["dataclass_transform"]),
                )
            {
                original_class_type
                    .d()
                    .shared
                    .get()
                    .class_data_class_transform
                    .set(validate_data_class_transform_decorator(
                        evaluator, call_node, node_info,
                    ));
            }
        }
    }

    let apply_dataclass_transform = || -> bool {
        // Is this a dataclass decorator?
        let mut call_node: Option<CallNode> = None;

        let dataclass_behaviors = if decorator_node.d().expr.get().node_type == ParseNodeType::Call
        {
            let decorator_call_node = CallNode(decorator_node.d().expr.get());
            call_node = Some(decorator_call_node);
            let decorator_call_type = evaluator
                .get_type_of_expression(
                    decorator_call_node.d().left_expr.get(),
                    flags | EvalFlags::CallBaseDefaults,
                    None,
                )
                .type_
                .get();
            get_dataclass_decorator_behaviors(decorator_call_type)
        } else {
            let decorator_type = evaluator
                .get_type_of_expression(decorator_node.d().expr.get(), flags, None)
                .type_
                .get();
            get_dataclass_decorator_behaviors(decorator_type)
        };

        if let Some(dataclass_behaviors) = dataclass_behaviors {
            apply_data_class_decorator(
                evaluator,
                decorator_node.0,
                original_class_type,
                dataclass_behaviors,
                call_node,
                node_info,
            );
            return true;
        }

        false
    };

    if is_overloaded(decorator_type) {
        let dataclass_behaviors = get_dataclass_decorator_behaviors(decorator_type);
        if let Some(dataclass_behaviors) = dataclass_behaviors {
            apply_data_class_decorator(
                evaluator,
                decorator_node.0,
                original_class_type,
                dataclass_behaviors,
                /* callNode */ None,
                node_info,
            );
            return input_class_type;
        }
    } else if is_function(decorator_type) {
        let decorator_function = FunctionType(decorator_type);
        let original_shared = original_class_type.d().shared.get();
        if FunctionType::is_built_in(decorator_function, Some(&["disjoint_base"])) {
            if ClassType::is_typed_dict_class(original_class_type) {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportGeneralTypeIssues,
                    &LocMessage::disjoint_base_typed_dict(),
                    decorator_node.d().expr.get(),
                    None,
                );
            } else if ClassType::is_protocol_class(original_class_type) {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportGeneralTypeIssues,
                    &LocMessage::disjoint_base_protocol(),
                    decorator_node.d().expr.get(),
                    None,
                );
            } else {
                original_shared
                    .flags
                    .set(original_shared.flags.get() | ClassTypeFlags::DisjointBase);
            }

            return input_class_type;
        }

        if FunctionType::is_built_in(decorator_function, Some(&["final"])) {
            original_shared
                .flags
                .set(original_shared.flags.get() | ClassTypeFlags::Final);

            // Don't call getTypeOfDecorator for final. We'll hard-code its
            // behavior because its function definition results in a cyclical
            // dependency between builtins, typing and _typeshed stubs.
            return input_class_type;
        }

        if FunctionType::is_built_in(decorator_function, Some(&["type_check_only"])) {
            original_shared
                .flags
                .set(original_shared.flags.get() | ClassTypeFlags::TypeCheckOnly);
            return input_class_type;
        }

        if FunctionType::is_built_in(decorator_function, Some(&["runtime_checkable"])) {
            original_shared
                .flags
                .set(original_shared.flags.get() | ClassTypeFlags::RuntimeCheckable);

            // Don't call getTypeOfDecorator for runtime_checkable. It appears
            // frequently in stubs, and it's a waste of time to validate its
            // parameters.
            return input_class_type;
        }

        if apply_dataclass_transform() {
            return input_class_type;
        }
    } else if is_class_instance(decorator_type) {
        let decorator_class = ClassType(decorator_type);
        if ClassType::is_built_in(decorator_class, Some(&["deprecated"])) {
            let deprecated_message = decorator_class
                .d()
                .priv_
                .borrow()
                .cold().deprecated_instance_message
                .clone();
            *original_class_type
                .d()
                .shared
                .get()
                .deprecated_message
                .borrow_mut() = deprecated_message;
            return input_class_type;
        }

        if apply_dataclass_transform() {
            return input_class_type;
        }
    }

    get_type_of_decorator(evaluator, decorator_node, input_class_type, node_info)
}

// analyzer/decorators.ts:450
pub(crate) fn get_type_of_decorator(
    evaluator: &TypeEvaluator,
    node: DecoratorNode,
    function_or_class_type: P<Type>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    // Evaluate the type of the decorator expression.
    let mut flags = if node_info.get_file_info(node.0).is_stub_file {
        EvalFlags::ForwardRefs
    } else {
        EvalFlags::None
    };
    if node.d().expr.get().node_type != ParseNodeType::Call {
        flags |= EvalFlags::CallBaseDefaults;
    }

    let decorator_type_result = evaluator.get_type_of_expression(node.d().expr.get(), flags, None);

    // Special-case the combination of a classmethod decorator applied
    // to a property. This is allowed in Python 3.9, but it's not reflected
    // in the builtins.pyi stub for classmethod.
    if is_instantiable_class(decorator_type_result.type_.get())
        && ClassType::is_built_in(
            ClassType(decorator_type_result.type_.get()),
            Some(&["classmethod"]),
        )
        && is_property(function_or_class_type)
    {
        return function_or_class_type;
    }

    let arg_list: Vec<Arg> = vec![Arg::ArgWithType(P::new_eval(ArgWithType {
        arg_category: ArgCategory::Simple,
        node: None,
        name: None,
        type_result: P::new_eval(TypeResult::new(function_or_class_type)),
        value_expression: None,
        active: None,
        enforce_iterable: None,
    }))];

    let call_type_result = evaluator.validate_call_args(
        node.d().expr.get(),
        &arg_list,
        decorator_type_result,
        /* constraints */ None,
        /* skipUnknownArgCheck */ Some(true),
        /* inferenceContext */ None,
        0,
    );

    let node_type_result_type = call_type_result
        .return_type
        .unwrap_or_else(|| UnknownType::create(false).0);
    evaluator.set_type_result_for_node(
        node.0,
        P::new_eval(TypeResult {
            cold: TypeResultCold {
                overloads_used_for_call: call_type_result.overloads_used_for_call.clone(),
                ..Default::default()
            }
            .into_cold(),
            is_incomplete: Cell::new(call_type_result.is_type_incomplete),
            ..TypeResult::new(node_type_result_type)
        }),
        EvalFlags::None,
    );

    let return_type = call_type_result
        .return_type
        .unwrap_or_else(|| UnknownType::create(false).0);

    // If the return type is a function that has no annotations
    // and just *args and **kwargs parameters, assume that it
    // preserves the type of the input function.
    if is_function(return_type)
        && FunctionType(return_type)
            .d()
            .shared
            .get()
            .declared_return_type
            .get()
            .is_none()
    {
        let parameters = FunctionType(return_type).d().shared.get().parameters.get();
        let has_disallowed_param = parameters
            .borrow()
            .iter()
            .enumerate()
            .any(|(index, param)| {
                // Don't allow * or / separators or params with declared types.
                if param.name.as_ref().is_none_or(|name| name.is_empty())
                    || FunctionParam::is_type_declared(param)
                {
                    return true;
                }

                // Allow *args or **kwargs parameters.
                if param.category != ParamCategory::Simple {
                    return false;
                }

                // Allow inferred "self" or "cls" parameters.
                index != 0 || !FunctionParam::is_type_inferred(param)
            });
        if !has_disallowed_param {
            return function_or_class_type;
        }
    }

    // If the decorator is completely unannotated and the return type
    // includes unknowns, assume that it preserves the type of the input
    // function.
    if is_partly_unknown(return_type, 0) && is_function(decorator_type_result.type_.get()) {
        let decorator_shared = FunctionType(decorator_type_result.type_.get())
            .d()
            .shared
            .get();
        let has_declared_param = decorator_shared
            .parameters
            .get()
            .borrow()
            .iter()
            .any(FunctionParam::is_type_declared);
        if !has_declared_param && decorator_shared.declared_return_type.get().is_none() {
            return function_or_class_type;
        }
    }

    return_type
}

// analyzer/decorators.ts:544
// Given a function node and the function type associated with it, this
// method searches for prior function nodes that are marked as @overload
// and creates an OverloadedType that includes this function and
// all previous ones.
pub fn add_overloads_to_function_type(
    evaluator: &TypeEvaluator,
    node: FunctionNode,
    type_: P<Type>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    let mut function_decl: Option<P<Declaration>> = None;
    let mut implementation: Option<P<Type>> = None;

    let decl = node_info.get_declaration(node);
    if let Some(decl) = decl {
        function_decl = Some(decl);
    }
    let symbol_with_scope = evaluator.look_up_symbol_recursive(
        node.0,
        &node.d().name.get().d().value,
        /* honorCodeFlow */ false,
        false,
    );
    if let Some(symbol_with_scope) = symbol_with_scope {
        let decls = symbol_with_scope.symbol.get_declarations();

        // Find this function's declaration.
        let decl_index = decls
            .iter()
            .position(|decl| Some(*decl) == function_decl)
            .map_or(-1, |index| index as i32);
        if decl_index > 0 {
            // Evaluate all of the previous function declarations. They will
            // be cached. We do it in this order to avoid a stack overflow due
            // to recursion if there is a large number (1000's) of overloads.
            for decl in &decls[..decl_index as usize] {
                if decl.type_ == DeclarationType::Function {
                    evaluator.get_type_of_function(FunctionNode(decl.node.get()));
                }
            }

            let mut overloaded_types: Vec<FunctionType> = Vec::new();

            // Look at the previous declaration's type.
            let prev_decl = decls[(decl_index - 1) as usize];
            if prev_decl.type_ == DeclarationType::Function {
                let prev_decl_decl_type_info =
                    evaluator.get_type_of_function(FunctionNode(prev_decl.node.get()));
                if let Some(prev_decl_decl_type_info) = prev_decl_decl_type_info {
                    let decorated_type = prev_decl_decl_type_info.decorated_type;
                    if is_function(decorated_type) {
                        if FunctionType::is_overloaded(FunctionType(decorated_type)) {
                            overloaded_types.push(FunctionType(decorated_type));
                        }
                    } else if is_overloaded(decorated_type) {
                        implementation =
                            OverloadedType::get_implementation(OverloadedType(decorated_type));
                        // If the previous overloaded function already had an implementation,
                        // this new function completely replaces the previous one.
                        if implementation.is_some() {
                            return type_;
                        }

                        // If the previous declaration was itself an overloaded function,
                        // copy the entries from it.
                        overloaded_types.extend(OverloadedType::get_overloads(OverloadedType(
                            decorated_type,
                        )));
                    }
                }
            }

            if is_function(type_) && FunctionType::is_overloaded(FunctionType(type_)) {
                overloaded_types.push(FunctionType(type_));
            } else {
                implementation = Some(type_);
            }

            if overloaded_types.len() == 1 && implementation.is_none() {
                return overloaded_types[0].0;
            }

            if overloaded_types.is_empty()
                && let Some(implementation) = implementation
            {
                return implementation;
            }

            // Apply the implementation's docstring to any overloads that don't
            // have their own docstrings.
            if let Some(implementation) = implementation
                && is_function(implementation)
            {
                let implementation_doc_string = FunctionType(implementation)
                    .d()
                    .shared
                    .get()
                    .cold().doc_string
                    .clone();
                if let Some(doc_string) = implementation_doc_string
                    && !doc_string.is_empty()
                {
                    overloaded_types = overloaded_types
                        .into_iter()
                        .map(|overload| {
                            if FunctionType::is_overloaded(overload)
                                && overload
                                    .d()
                                    .shared
                                    .get()
                                    .cold().doc_string
                                    .as_ref()
                                    .is_none_or(|overload_doc| overload_doc.is_empty())
                            {
                                return FunctionType::clone_with_doc_string(
                                    overload,
                                    Some(doc_string.clone()),
                                );
                            }
                            overload
                        })
                        .collect();
                }
            }

            // PEP 702 indicates that if the implementation of an overloaded
            // function is marked deprecated, all of the overloads should be
            // treated as deprecated as well.
            if let Some(implementation) = implementation
                && is_function(implementation)
            {
                let implementation_deprecated_message = FunctionType(implementation)
                    .d()
                    .shared
                    .get()
                    .cold().deprecated_message
                    .clone();
                if let Some(deprecation_message) = implementation_deprecated_message {
                    overloaded_types = overloaded_types
                        .into_iter()
                        .map(|overload| {
                            if FunctionType::is_overloaded(overload)
                                && overload
                                    .d()
                                    .shared
                                    .get()
                                    .cold().deprecated_message
                                    .is_none()
                            {
                                return FunctionType::clone_with_deprecated_message(
                                    overload,
                                    Some(deprecation_message.clone()),
                                );
                            }
                            overload
                        })
                        .collect();
                }
            }

            return OverloadedType::create(&overloaded_types, implementation).0;
        }
    }

    type_
}

// analyzer/decorators.ts:648
// Given a @typing.deprecated call node, returns either '' or a custom
// deprecation message if one is provided.
pub fn get_deprecated_message_from_call(node: CallNode) -> String {
    let args = node.d().args.borrow().clone();
    if !args.is_empty()
        && args[0].d().arg_category.get() == ArgCategory::Simple
        && args[0].d().value_expr.get().node_type == ParseNodeType::StringList
    {
        let string_list_node = StringListNode(args[0].d().value_expr.get());
        let mut message = JsString::from("");
        for s in string_list_node.d().strings.borrow().iter() {
            let value = match s.d() {
                ParseNodeDetails::String(d) => &d.value,
                ParseNodeDetails::FormatString(d) => &d.value,
                _ => unreachable!("a string list holds string nodes"),
            };
            message = message.concat(value);
        }
        return convert_doc_string_to_plain_text(&message.to_string_lossy());
    }

    String::new()
}
